-- PopTracker pack for Pokemon HGSS Singe.
-- data.lua, items, locations and maps are generated by tracker_gen.py from
-- this world's own data (data_gen/); only the scripts in this folder are
-- written by hand.

ScriptHost:LoadScript("scripts/data.lua")
ScriptHost:LoadScript("scripts/logic.lua")

-- One variant per language; section names (and so their codes) differ.
DATA.location_sections = DATA.location_sections_by_lang[Tracker.ActiveVariantUID]
    or DATA.location_sections_by_lang["en"]

Tracker:AddItems("items/items.json")
Tracker:AddMaps("maps/maps.json")
Tracker:AddLocations("locations/locations.json")
Tracker:AddLayouts("layouts/tracker.json")
Tracker:AddLayouts("layouts/broadcast.json")

if PopVersion and Archipelago then
    ScriptHost:LoadScript("scripts/autotracking.lua")
    ScriptHost:LoadScript("scripts/spoiler.lua")
end
